"use strict";$(function(){var a=$(".copy-cite-link"),b="Copy DOI to clipboard";$(".copy-cite-link").click(function(){var c=a.parent().attr("href");return navigator.clipboard.writeText(c).then(function(){a.attr("data-original-title","Copied!").tooltip("show"),a.attr("data-original-title",b)}),!1}),a.tooltip({title:b})});
